// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract TokenRecorder {
    address public lastFrom;
    address public lastTo;
    uint256 public lastAmount;
    bytes4 public lastSelector;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        lastSelector = msg.sig;
        lastFrom = from;
        lastTo = to;
        lastAmount = amount;
        return true;
    }
}

contract InvMutTest is Test {
    demo c;

    function setUp() public {
        c = new demo();
    }

    function testFuzz_property(address from, address recipient, uint256 amount) public {
        // Keep the fuzzed domain wide but make the token actually record
        TokenRecorder token = new TokenRecorder();
        address[] memory tos = new address[](1);
        tos[0] = recipient;

        bool ok = c.transfer(from, address(token), tos, amount);
        assertTrue(ok && token.lastFrom() == from);
    }
}
